def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    routes = {
        1: [(0, 1), (0, 1), (-1, 0)],
        2: [(0, -1)] * 4,
        3: [(1, 0)] * 3,
        6: [(-1, 0)] * 6,
    }
    visits = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in routes:
                continue
            rr, cc = r, c
            for i, (dr, dc) in enumerate(routes[color]):
                rr, cc = rr + dr, cc + dc
                if not (0 <= rr < h and 0 <= cc < w):
                    break
                visits.setdefault((rr, cc), set()).add(color)
                out[rr][cc] = color if i == len(routes[color]) - 1 else 5
    # At the crossing of the westward 2-trail with a vertical 3/6-trail,
    # create a 4 and continue diagonally down-left to the grid edge.
    crossings = [(r, c) for (r, c), colors in visits.items()
                 if 2 in colors and (3 in colors or 6 in colors)]
    for r, c in crossings:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
